#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
deploy_all.py — يعدل على السيرفر مباشر
شغّله بـ: python3 deploy_all.py
"""
import base64, os, shutil

BASE = '/opt/retal-api'

# ── الملفات المضمّنة كـ base64 ──────────────────────────────
# src/pages/Login.tsx
src_pages_Login_tsx = ""

# src/components/clients/ClientForm.tsx
src_components_clients_ClientForm_tsx = ""

# src/components/projects/ProjectForm.tsx
src_components_projects_ProjectForm_tsx = ""

# src/pages/ProjectDetail.tsx
src_pages_ProjectDetail_tsx = ""

# server/routes/import-excel.ts
server_routes_import_excel_ts = ""

# ── خريطة المسارات ─────────────────────────────────────────
FILES = {
    f'{BASE}/src/pages/Login.tsx': src_pages_Login_tsx,
    f'{BASE}/src/components/clients/ClientForm.tsx': src_components_clients_ClientForm_tsx,
    f'{BASE}/src/components/projects/ProjectForm.tsx': src_components_projects_ProjectForm_tsx,
    f'{BASE}/src/pages/ProjectDetail.tsx': src_pages_ProjectDetail_tsx,
    f'{BASE}/server/routes/import-excel.ts': server_routes_import_excel_ts,
}

# ── التطبيق ─────────────────────────────────────────────────
print("\n📦 تطبيق التعديلات…\n")
for dest, b64 in FILES.items():
    bak = dest + ".bak"
    if os.path.exists(dest):
        shutil.copy2(dest, bak)
        print(f"  backup  {bak}")
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    with open(dest, "wb") as fh:
        fh.write(base64.b64decode(b64))
    print(f"  ✅ {dest}")

print("\n🚀 build + restart…")
ret = os.system(f"cd {BASE} && npm run build && pm2 restart retal-api")
if ret == 0:
    print("\n✅ تم النشر بنجاح")
else:
    print("\n❌ فشل الـ build — راجع الأخطاء فوق")